/bin/bash -c "python3 - <<'PY'
from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
links=set()
for p in r.pages:
 for a in p.get('/Annots',[]):
  o=a.get_object()
  action=o.get('/A')
  if action and action.get('/URI'):
   links.add(str(action['/URI']))
for link in sorted(links):
 if not any(d in link for d in ['doi.org','aclanthology.org','arxiv.org','openreview.net','huggingface.co','mailto:']):
  print(link)
print('Total distinct external links:',len(links))
PY"
